gold_sql:
SELECT COUNT(*) AS active_store_count
FROM demo_sales.stores
WHERE close_date IS NULL;

SELECT SUM(total_amount) AS sales_amount
FROM demo_sales.sales
WHERE sold_at >= '2026-07-01' AND sold_at < '2026-08-01';

SELECT COUNT(*) AS txn_count
FROM demo_sales.sales
WHERE payment_method = '電子マネー';

SELECT COUNT(*) AS active_product_count
FROM demo_sales.products
WHERE is_discontinued = false;

SELECT ROUND(100.0 * SUM(total_amount) FILTER (WHERE channel IN ('EC','オンライン'))
             / SUM(total_amount), 1) AS ec_share_pct
FROM demo_sales.sales;

SELECT COUNT(*) AS kansai_store_count
FROM demo_sales.stores
WHERE region IN ('関西','近畿');

SELECT ROUND(100.0 * COUNT(*) FILTER (WHERE i.unit_price < p.unit_price) / COUNT(*), 1) AS discounted_pct
FROM demo_sales.sale_items i
JOIN demo_sales.products p ON p.product_id = i.product_id;

SELECT ROUND(100.0 * (
      SUM(total_amount) FILTER (WHERE sold_at >= '2026-07-01' AND sold_at < '2026-08-01')
    - SUM(total_amount) FILTER (WHERE sold_at >= '2025-07-01' AND sold_at < '2025-08-01')
  ) / SUM(total_amount) FILTER (WHERE sold_at >= '2025-07-01' AND sold_at < '2025-08-01'), 1) AS yoy_pct
FROM demo_sales.sales;

SELECT SUM(i.quantity * p.unit_price) - SUM(i.line_amount) AS gap
FROM demo_sales.sale_items i
JOIN demo_sales.products p ON p.product_id = i.product_id;
